tools.example:
Model model = ModelUtil.create("Model");
model.component().create("comp1", true);
GeomSequence g = model.component("comp1").geom().create("geom1", 3);
g.lengthUnit("mm");
g.create("blk1", "Block");
g.feature("blk1").set("size", new String[]{"20", "10", "5"});
g.feature("blk1").set("base", "center");
g.feature("blk1").set("pos", new String[]{"0", "0", "0"});
g.feature("blk1").set("selresult", "on");
g.run();

GeomSequence g = model.component("comp1").geom("geom1");
g.create("cyl1", "Cylinder");
g.feature("cyl1").set("r", "5[mm]");
g.feature("cyl1").set("h", "40[mm]");
g.feature("cyl1").set("pos", new String[]{"0", "0", "-20[mm]"});
g.feature("cyl1").set("axis", new double[]{0, 0, 1});
// a pipe: 1 mm wall as a separate layer
g.feature("cyl1").set("layer", new String[]{"1[mm]"});
g.feature("cyl1").set("layerside", "on");
g.run("cyl1");

GeomSequence g = model.component("comp1").geom("geom1");
g.create("sph1", "Sphere");
g.feature("sph1").set("r", "0.1");
g.feature("sph1").set("pos", new double[]{0, 0, 0});
g.feature("sph1").set("layer", new String[]{"0.02"});   // 20 mm outer shell
g.feature("sph1").set("sellayer", "on");
g.run("sph1");

GeomSequence g = model.component("comp1").geom("geom1");
g.angularUnit("deg");
g.create("cone1", "Cone");
g.feature("cone1").set("r", 2);
g.feature("cone1").set("h", 3);
g.feature("cone1").set("specifytop", "angle");
g.feature("cone1").set("ang", 30);
g.feature("cone1").set("pos", new double[]{0, 0, 0});
g.run("cone1");

GeomSequence g = model.component("comp1").geom("geom1");
g.create("tor1", "Torus");
g.feature("tor1").set("rmaj", 10);
g.feature("tor1").set("rmin", 2);
g.feature("tor1").set("angle", 90);      // quarter bend
g.feature("tor1").set("pos", "0,0,0");
g.feature("tor1").set("axis", "0,0,1");
g.run("tor1");

GeomSequence g = model.component("comp1").geom().create("geom1", 2);
g.lengthUnit("mm");
g.create("r1", "Rectangle");
g.feature("r1").set("size", new String[]{"W", "H"});   // parameters
g.feature("r1").set("base", "center");
g.feature("r1").set("pos", new String[]{"0", "0"});
// three horizontal layers stacked from the bottom
g.feature("r1").set("layer", new String[]{"0.5", "1.5"});
g.feature("r1").set("layerbottom", "on");
g.run("r1");

GeomSequence g = model.component("comp1").geom("geom1");   // 2D
g.create("c1", "Circle");
g.feature("c1").set("r", "R_out");
g.feature("c1").set("pos", new double[]{2, 3});
g.feature("c1").set("layer", new String[]{"R_out-R_in"});   // annulus as a layer
g.run("c1");

GeomSequence g = model.component("comp1").geom("geom1");   // 2D
g.create("pol1", "Polygon");
g.feature("pol1").set("x", "0, 2, 2, 0");
g.feature("pol1").set("y", "0, 0, 1, 1");
g.feature("pol1").set("type", "solid");
g.run("pol1");

// or from a coordinate table
g.create("pol2", "Polygon");
g.feature("pol2").set("table", new double[][]{{0,0}, {1,0}, {1,1}, {0,1}});

GeomSequence g = model.component("comp1").geom("geom1");   // 3D
g.create("wp1", "WorkPlane");
g.feature("wp1").set("quickplane", "yz");
g.feature("wp1").set("quickx", 0.5);
g.feature("wp1").geom().create("r1", "Rectangle");
g.feature("wp1").geom().feature("r1").set("size", new String[]{"2", "1"});
g.feature("wp1").geom().feature("r1").set("pos", "1 1");
g.run("wp1");

// plane parallel to an existing face
g.create("wp2", "WorkPlane");
g.feature("wp2").set("planetype", "faceparallel");
g.feature("wp2").selection("face").set("blk1", new int[]{1});
g.feature("wp2").set("reverse", "on");

GeomSequence g = model.component("comp1").geom("geom1");
g.create("wp1", "WorkPlane");
g.feature("wp1").geom().create("c1", "Circle");
g.run("wp1");
g.create("ext1", "Extrude");
g.feature("ext1").set("distance", 1.3);
g.run();

// two stacked sections with a taper on the second
g.create("ext2", "Extrude");
g.feature("ext2").set("distance", new String[]{"1", "2"});
g.feature("ext2").setIndex("scale", "0.5", 1, 0);

GeomSequence g = model.component("comp1").geom("geom1");
g.create("wp1", "WorkPlane");
g.feature("wp1").geom().create("c1", "Circle");
g.feature("wp1").geom().feature("c1").set("pos", "2 0");
g.run("wp1");
g.create("rev1", "Revolve");
g.feature("rev1").set("angle1", 0);
g.feature("rev1").set("angle2", 360);
g.run();

GeomSequence g = model.component("comp1").geom("geom1");
g.create("wp1", "WorkPlane");
g.feature("wp1").geom().create("c1", "Circle");
g.create("pc1", "ParametricCurve");
g.feature("pc1").set("parmax", "pi");
g.feature("pc1").set("coord", new String[]{"(cos(s)-1)*3", "0", "sin(s)*3"});
g.create("swe1", "Sweep");
g.feature("swe1").selection("enttosweep").set("wp1.c1", new int[]{1});
g.feature("swe1").selection("edge").set("pc1(1)", new int[]{1});
g.run();

GeomSequence g = model.component("comp1").geom("geom1");
g.create("r1", "Rectangle");
g.create("c1", "Circle");
g.create("uni1", "Union");
g.feature("uni1").selection("input").set(new String[]{"r1", "c1"});
g.feature("uni1").set("intbnd", "off");   // one single domain
g.run();

GeomSequence g = model.component("comp1").geom("geom1");   // 3D
g.create("blk1", "Block");
g.feature("blk1").set("size", "10 14 5");
g.feature("blk1").set("pos", "-3 -5 -4");
g.create("cyl1", "Cylinder");
g.feature("cyl1").set("r", 1);
g.feature("cyl1").set("h", 10);
g.create("dif1", "Difference");
g.feature("dif1").selection("input").set("blk1");
g.feature("dif1").selection("input2").set("cyl1");
g.feature("dif1").set("keepsubtract", "off");
g.run();

GeomSequence g = model.component("comp1").geom("geom1");   // 3D
g.create("cyl1", "Cylinder");
g.feature("cyl1").set("h", 10);
g.create("wp1", "WorkPlane");
g.feature("wp1").set("planetype", "general");
g.feature("wp1").setIndex("genpoints", 4, 0, 2);
g.feature("wp1").setIndex("genpoints", 5, 1, 2);
g.feature("wp1").setIndex("genpoints", 5, 2, 2);
g.create("par1", "Partition");
g.feature("par1").selection("input").set("cyl1");
g.feature("par1").set("partitionwith", "workplane");
g.run("par1");

GeomSequence g = model.component("comp1").geom("geom1");   // 3D
g.create("cyl1", "Cylinder");
g.create("arr1", "Array");
g.feature("arr1").selection("input").set("cyl1");
g.feature("arr1").set("displ", "4 4 0");
g.feature("arr1").set("size", "2 2 1");
g.create("blk1", "Block");
g.feature("blk1").set("size", "10 14 5");
g.feature("blk1").set("pos", "-3 -5 -4");
g.create("dif1", "Difference");
g.feature("dif1").selection("input").set("blk1");
g.feature("dif1").selection("input2").set("arr1");
g.run();

GeomSequence g = model.component("comp1").geom("geom1");   // 2D
g.create("c1", "Circle");
g.create("mov1", "Move");
g.feature("mov1").selection("input").set("c1");
g.feature("mov1").set("displ", new double[][]{{2}, {3}});
g.run("mov1");

// a translated duplicate instead
g.create("copy1", "Copy");
g.feature("copy1").selection("input").set("c1");
g.feature("copy1").set("displz", "10[mm]");

GeomSequence g = model.component("comp1").geom("geom1");   // 2D
g.create("e1", "Ellipse");
g.feature("e1").set("semiaxes", "1 3");
g.create("rot1", "Rotate");
g.feature("rot1").selection("input").set("e1");
g.feature("rot1").set("rot", 10);
g.feature("rot1").set("pos", "2 3");
g.run();

// circular pattern of six copies in 3D
g.create("rot2", "Rotate");
g.feature("rot2").selection("input").set("blk1");
g.feature("rot2").set("axis", "0 0 1");
g.feature("rot2").set("rot", "60,120,180,240,300");
g.feature("rot2").set("keep", "on");

GeomSequence g = model.component("comp1").geom("geom1");   // 2D
g.create("r1", "Rectangle");
g.create("mir1", "Mirror");
g.feature("mir1").selection("input").set("r1");
g.feature("mir1").set("pos", "2 2");
g.feature("mir1").set("axis", "1 1");
g.feature("mir1").set("keep", "on");
g.create("uni1", "Union");
g.feature("uni1").selection("input").set(new String[]{"r1", "mir1"});
g.run();

GeomSequence g = model.component("comp1").geom("geom1");   // 2D
g.create("r1", "Rectangle");
g.create("fil1", "Fillet");
g.feature("fil1").selection("point").set("r1(1)", new int[]{1, 2, 3, 4});
g.feature("fil1").set("radius", 0.1);
g.run();

GeomSequence g = model.component("comp1").geom("geom1");
// the finalize feature must use the tag "fin"
g.create("fin", "FormUnion");
g.feature("fin").set("action", "union");
g.feature("fin").set("repairtoltype", "auto");
g.run();

// assembly with contact pairs instead
g.create("fin", "FormAssembly");
g.feature("fin").set("action", "assembly");
g.feature("fin").set("pairtype", "contact");
g.feature("fin").set("imprint", "on");

GeomSequence g = model.component("comp1").geom("geom1");

// COMSOL native objects
g.create("imp1", "Import");
g.feature("imp1").set("filename", "C:/work/part.mphbin");
g.feature("imp1").set("selresult", "on");
g.feature("imp1").importData();

// 3D CAD file (CAD Import Module, Design Module or a LiveLink product)
g.create("imp2", "Import");
g.feature("imp2").set("filename", "C:/work/housing.step");
g.feature("imp2").set("type", "cad");
g.feature("imp2").set("unit", "source");
g.feature("imp2").set("repair", "on");
g.feature("imp2").set("importtol", 1e-5);
g.feature("imp2").set("knit", "solid");
g.feature("imp2").set("selindividual", "on");
g.run();
